  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration)
  }

  /** helper function to set the values of all input ports.
   * @param docking_proposal payload for data port docking_proposal
   * @param access_proposal payload for data port access_proposal
   * @param undocking_proposal payload for data port undocking_proposal
   * @param priority_directive payload for data port priority_directive
   */
  def put_concrete_inputs(docking_proposal : Docking_Access_Supervisor.DockingProposal,
                          access_proposal : Docking_Access_Supervisor.AccessProposal,
                          undocking_proposal : Docking_Access_Supervisor.UndockingProposal,
                          priority_directive : Docking_Access_Supervisor.PriorityDirective): Unit = {
    put_docking_proposal(docking_proposal)
    put_access_proposal(access_proposal)
    put_undocking_proposal(undocking_proposal)
    put_priority_directive(priority_directive)
  }


  /** helper function to check DockingActionArbitration_supervisor_process_docking_action_arbitration's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param docking_decision method that will be called with the value of the outgoing data
   *        port 'docking_decision'.
   */
  def check_concrete_output(docking_decision: Docking_Access_Supervisor.DockingDecisionFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val docking_decisionValue: Docking_Access_Supervisor.DockingDecisionFrame = get_docking_decision().get
    if(!docking_decision(docking_decisionValue)) {
      testFailures = testFailures :+ st"'docking_decision' did not match expected: value of the outgoing data port is ${docking_decisionValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_docking_proposal(value : Docking_Access_Supervisor.DockingProposal): Unit = {
    Art.insertInInfrastructurePort(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration.operational_api.docking_proposal_Id, Docking_Access_Supervisor.DockingProposal_Payload(value))
  }

  // setter for in DataPort
  def put_access_proposal(value : Docking_Access_Supervisor.AccessProposal): Unit = {
    Art.insertInInfrastructurePort(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration.operational_api.access_proposal_Id, Docking_Access_Supervisor.AccessProposal_Payload(value))
  }

  // setter for in DataPort
  def put_undocking_proposal(value : Docking_Access_Supervisor.UndockingProposal): Unit = {
    Art.insertInInfrastructurePort(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration.operational_api.undocking_proposal_Id, Docking_Access_Supervisor.UndockingProposal_Payload(value))
  }

  // setter for in DataPort
  def put_priority_directive(value : Docking_Access_Supervisor.PriorityDirective): Unit = {
    Art.insertInInfrastructurePort(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration.operational_api.priority_directive_Id, Docking_Access_Supervisor.PriorityDirective_Payload(value))
  }

  // getter for out DataPort
  def get_docking_decision(): Option[Docking_Access_Supervisor.DockingDecisionFrame] = {
    val value: Option[Docking_Access_Supervisor.DockingDecisionFrame] = get_docking_decision_payload() match {
      case Some(Docking_Access_Supervisor.DockingDecisionFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port docking_decision.  Expecting 'Docking_Access_Supervisor.DockingDecisionFrame_Payload' but received ${v}")
      case _ => None[Docking_Access_Supervisor.DockingDecisionFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_docking_decision_payload(): Option[Docking_Access_Supervisor.DockingDecisionFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.DockingAccessSupervisorSystem_Instance_supervisor_process_docking_action_arbitration.initialization_api.docking_decision_Id).asInstanceOf[Option[Docking_Access_Supervisor.DockingDecisionFrame_Payload]]
